pub fn count_passing(scores: &[u32], pass_mark: u32) -> usize {
    let mut count = 0;
    for &s in scores {
        if s >= pass_mark {
            count += 1;
        }
    }
    count
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_scores_above_the_mark() {
        assert_eq!(count_passing(&[50, 70, 90], 60), 2);
    }

    #[test]
    fn score_equal_to_mark_passes() {
        assert_eq!(count_passing(&[60], 60), 1);
    }

    #[test]
    fn empty_list_has_no_passes() {
        assert_eq!(count_passing(&[], 60), 0);
    }

    #[test]
    fn first_score_is_counted() {
        assert_eq!(count_passing(&[80, 10], 50), 1);
    }
}

