pub enum MoneyError {
    Insufficient,
    Overflow,
}

pub struct Account {
    balance: u32,
}

impl Account {
    pub fn new(balance: u32) -> Self {
        Self { balance }
    }

    pub fn balance(&self) -> u32 {
        self.balance
    }
}

fn can_receive(balance: u32, amount: u32) -> bool {
    amount <= u32::MAX - balance
}

pub fn transfer(a: &mut Account, b: &mut Account, amount: u32) -> Result<(), MoneyError> {
    if a.balance < amount {
        return Err(MoneyError::Insufficient);
    }
    if !can_receive(b.balance, amount) {
        return Err(MoneyError::Overflow);
    }
    a.balance -= amount;
    b.balance += amount;
    Ok(())
}

