#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn counts_characters_not_bytes() {
        assert_eq!(scalar_len("abc"), 3, "three ASCII letters");
        assert_eq!(scalar_len("éé"), 2, "two characters, four bytes");
        assert_eq!(scalar_len(""), 0, "empty text");
        assert_eq!(
            scalar_len("e\u{301}"),
            2,
            "a letter and a combining accent are two characters"
        );
    }
}

pub fn unicode_fixture() -> String {
    String::from("\u{3000}éé\tabc\u{3000}")
}

mod common;

use test_lab::{View, first_word, longest_word, normalize, same_location};

#[test]
fn finds_the_first_word() {
    assert_eq!(first_word("hello world"), "hello");
}

#[test]
fn the_first_word_is_borrowed_from_the_input() {
    let text = common::unicode_fixture();
    let word = first_word(&text);
    assert_eq!(word, "éé", "U+3000 is whitespace");
    assert!(
        same_location(word, &text[3..7]),
        "the word is a slice of the input, not a copy"
    );
}

#[test]
fn no_words_give_the_empty_slice_at_the_start() {
    let blank = String::from(" \t ");
    assert_eq!(first_word(&blank), "");
    assert!(
        same_location(first_word(&blank), &blank[0..0]),
        "first_word points at the start"
    );
    assert!(
        same_location(longest_word(&blank), &blank[0..0]),
        "longest_word points at the start"
    );
}

#[test]
fn the_longest_word_counts_characters() {
    let text = common::unicode_fixture();
    let word = longest_word(&text);
    assert_eq!(word, "abc", "3 characters beat 2, though éé has more bytes");
    assert!(same_location(word, &text[8..11]), "the slice of the input");
}

#[test]
fn the_first_of_equal_words_wins() {
    let text = String::from("ab cd");
    assert!(
        same_location(longest_word(&text), &text[0..2]),
        "ab comes first"
    );
}

#[test]
fn normalize_collapses_inner_runs() {
    assert_eq!(normalize("a  \t b\u{3000}\u{3000}c"), "a b c");
    assert_eq!(normalize(&common::unicode_fixture()), "éé abc");
}

#[test]
fn a_view_borrows_its_text() {
    let text = String::from("  first second");
    let view = View::new(&text);
    assert_eq!(view.first(), "first");
    assert!(
        same_location(view.first(), &text[2..7]),
        "first() is a slice of the text"
    );
    assert!(
        same_location(view.original(), &text),
        "original() is the whole text"
    );
}

