mod tests {
    use super::*;

    #[test]
    fn standard_and_premium_loans() {
        assert_eq!(due_day(10, false), 24, "a standard loan lasts 14 days");
        assert_eq!(due_day(10, true), 38, "a premium loan lasts 28 days");
    }

    #[test]
    fn early_and_on_time_returns_are_not_late() {
        assert_eq!(days_late(24, 20), 0, "returned four days early");
        assert_eq!(days_late(24, 24), 0, "returned on the due day");
        assert_eq!(days_late(24, 25), 1, "one day late");
    }

    #[test]
    fn fees_follow_the_two_rates_and_the_cap() {
        assert_eq!(late_fee_cents(7), 175, "the last day at 25 cents");
        assert_eq!(late_fee_cents(8), 225, "the first day at 50 cents");
        assert_eq!(late_fee_cents(43), 1975, "the last fee under the cap");
        assert_eq!(late_fee_cents(44), 2000, "the cap");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Library {
        let mut library = Library::new();
        library.add_book("Dune", "Frank Herbert", 1965);
        library.add_book("Emma", "Jane Austen", 1815);
        library.add_book("Ulysses", "James Joyce", 1922);
        library.add_book("Persuasion", "Jane Austen", 1817);
        library
    }

    #[test]
    fn index_of_finds_positions_by_id() {
        let library = sample();
        assert_eq!(library.index_of(1), Some(0), "the first book");
        assert_eq!(library.index_of(4), Some(3), "the last book");
        assert_eq!(library.index_of(9), None, "no book has id 9");
    }

    #[test]
    fn standard_members_borrow_three_and_premium_six() -> Result<(), LibraryError> {
        let mut library = sample();
        library.add_member(7, "Ada", false)?;
        library.add_member(8, "Bo", true)?;
        for id in 1..=3 {
            library.checkout(id, 7, 1)?;
        }
        assert_eq!(
            library.checkout(4, 7, 1),
            Err(LibraryError::LimitReached(7)),
            "a fourth book is over a standard member's limit"
        );
        match library.member(8) {
            Some(member) => assert_eq!(member.limit(), 6, "premium members may borrow six"),
            None => panic!("member 8 was added"),
        }
        Ok(())
    }

    #[test]
    fn returning_a_book_frees_a_place() -> Result<(), LibraryError> {
        let mut library = sample();
        library.add_member(7, "Ada", false)?;
        for id in 1..=3 {
            library.checkout(id, 7, 1)?;
        }
        library.return_book(2, 5)?;
        library.checkout(4, 7, 5)?;
        assert_eq!(
            library.count_by_status(),
            (1, 3, 0),
            "one on the shelf, three out"
        );
        Ok(())
    }

    #[test]
    fn members_are_sorted_by_id() -> Result<(), LibraryError> {
        let mut library = Library::new();
        library.add_member(30, "Cy", false)?;
        library.add_member(10, "Ann", false)?;
        library.add_member(20, "Bo", true)?;
        let mut ids = Vec::new();
        for member in library.members_sorted() {
            ids.push(member.id);
        }
        assert_eq!(ids, vec![10, 20, 30], "ascending ids");
        Ok(())
    }
}

use library::{Library, LibraryError, search};

fn stocked() -> Library {
    let mut library = Library::new();
    library.add_book(
        "The  Rust\tProgramming\u{3000}Language",
        "Steve Klabnik",
        2019,
    );
    library.add_book("Dune", "Frank Herbert", 1965);
    library
}

#[test]
fn a_complete_borrowing_cycle() -> Result<(), LibraryError> {
    let mut library = stocked();
    library.add_member(1, "Ada", false)?;
    let due = library.checkout(2, 1, 10)?;
    assert_eq!(due, 24, "a standard loan is due 14 days later");
    let fee = library.return_book(2, 32)?;
    assert_eq!(fee, 225, "8 days late: 7 × 25 + 1 × 50 cents");
    assert_eq!(library.count_by_status(), (2, 0, 0), "both books are back");
    Ok(())
}

#[test]
fn titles_are_normalized_when_added() {
    let library = stocked();
    match library.book(1) {
        Some(book) => assert_eq!(book.title, "The Rust Programming Language"),
        None => panic!("book 1 was added"),
    }
}

#[test]
fn title_search_ignores_case() {
    let library = stocked();
    assert_eq!(library.search_titles("rust programming"), vec![1]);
}

#[test]
fn find_needs_every_word_in_title_or_author() {
    let library = stocked();
    let found = library.find("klabnik rust");
    assert_eq!(found.len(), 1, "one word in the author, one in the title");
    assert_eq!(found[0].id, 1);
    assert_eq!(
        library.find("rust herbert").len(),
        0,
        "no book has both words"
    );
}

#[test]
fn search_through_references_needs_every_word() {
    let library = stocked();
    let books = library.find("");
    assert_eq!(books.len(), 2, "an empty query matches every book");
    let found = search(&books, "klabnik rust");
    assert_eq!(
        found.len(),
        1,
        "words in any order, in the title or the author"
    );
}
